:root[data-style="clean"] .dm-rtr-f,:root [data-style="clean"] .dm-rtr-f,:root [data-style="clean"].dm-rtr-f{display:flex;align-items:center;gap:8px;min-height:44px;margin:0;padding:0 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);font-size:12.5px;color:var(--dm-fg2);white-space:nowrap}
:root[data-style="clean"] .dm-rtr-fk,:root [data-style="clean"] .dm-rtr-fk,:root [data-style="clean"].dm-rtr-fk{display:grid;place-items:center;width:14px;height:14px;flex:none;border-radius:50%;background:var(--dm-ok-mark);color:var(--dm-surface)}
:root[data-style="clean"] .dm-rtr-fk svg,:root [data-style="clean"] .dm-rtr-fk svg,:root [data-style="clean"].dm-rtr-fk svg{width:8px;height:8px;stroke-width:3.6}
:root[data-style="clean"] .dm-rtr-fs,:root [data-style="clean"] .dm-rtr-fs,:root [data-style="clean"].dm-rtr-fs{margin-left:auto;color:var(--dm-muted);overflow:hidden;text-overflow:ellipsis}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .dm-rtr-li:is(.dm-just,.dm-next-in) *,:root [data-style="clean"] .dm-rtr-li:is(.dm-just,.dm-next-in) *,:root [data-style="clean"].dm-rtr-li:is(.dm-just,.dm-next-in) *,:root[data-style="clean"] .dm-rtr-li.dm-just::before,:root [data-style="clean"] .dm-rtr-li.dm-just::before,:root [data-style="clean"].dm-rtr-li.dm-just::before{animation:none!important}:root[data-style="clean"] .dm-rtr-li.dm-just>.dm-g>.dm-rtr-m path,:root [data-style="clean"] .dm-rtr-li.dm-just>.dm-g>.dm-rtr-m path,:root [data-style="clean"].dm-rtr-li.dm-just>.dm-g>.dm-rtr-m path{stroke-dashoffset:0}:root[data-style="clean"] [data-s="now"]>.dm-g>.dm-rtr-m,:root [data-style="clean"] [data-s="now"]>.dm-g>.dm-rtr-m,:root [data-style="clean"][data-s="now"]>.dm-g>.dm-rtr-m{animation:none}}
